import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression

MAX_DRIVERS = 5

def design(feats):
    # Filter out non-numeric features and identify strong candidates
    strong_candidates = []
    numeric_features = []

    for i, fid in enumerate(feats.ids):
        # Only consider numeric features (expression, copy_number)
        if feats.types[i] in ['expression', 'copy_number']:
            numeric_features.append(i)
            # Use t-statistic from the provided statistics
            t_stat = feats.types[i]  # This should be the t-stat value
            if isinstance(t_stat, (int, float)):
                effect_size = np.mean(feats.x[feats.y==1, i]) - np.mean(feats.x[feats.y==0, i])
                if abs(t_stat) > 2.5 or abs(effect_size) > 0.2:
                    strong_candidates.append((fid, abs(t_stat), abs(effect_size)))

    # Sort by t-statistic magnitude
    if strong_candidates:
        strong_candidates.sort(key=lambda x: x[1], reverse=True)
        # Select top candidates
        candidates = [fid for fid, _, _ in strong_candidates[:10]]
    else:
        candidates = []

    # Remove near-duplicates based on correlation
    keep = []
    for fid in candidates:
        is_duplicate = False
        for kept_fid in keep:
            col_a = feats.column(fid)
            col_b = feats.column(kept_fid)
            if abs(np.corrcoef(feats.x[:, col_a], feats.x[:, col_b])[0,1]) > 0.6:
                is_duplicate = True
                break
        if not is_duplicate:
            keep.append(fid)

    # Simple logistic regression to identify drivers
    if len(keep) > 0:
        X = feats.x[:, [feats.column(fid) for fid in keep]]
        lr = LogisticRegression(penalty='l1', solver='liblinear', C=0.1)
        lr.fit(X, feats.y)

        # Get feature importance (coefficients)
        coef = np.abs(lr.coef_[0])
        ranked_indices = np.argsort(coef)[::-1]

        # Select drivers based on coefficient magnitude
        drivers = [keep[i] for i in ranked_indices[:MAX_DRIVERS] if coef[i] > 0.1]
    else:
        drivers = []

    # Select all features that enter the model
    columns = keep

    # Check for interaction terms (simple approach)
    products = []
    for i, fid1 in enumerate(columns):
        for j, fid2 in enumerate(columns[i+1:], i+1):
            if np.corrcoef(feats.x[:, feats.column(fid1)], feats.x[:, feats.column(fid2)])[0,1] > 0.6:
                products.append((fid1, fid2))

    # Create loadings for weighted score
    loadings = {}
    for i, fid in enumerate(columns):
        if len(keep) > 0:
            loadings[fid] = coef[i] if i < len(coef) else 0.0
        else:
            loadings[fid] = 0.0

    return Design(drivers=tuple(drivers), columns=tuple(columns), products=tuple(products), loadings=loadings)

